/// 设备端输入状态快照(一次 `dumpsys input` 的解析结果)
#[derive(Debug, Clone, Default, PartialEq)]
pub struct DeviceInputState {
    pub inject_status: i64,        // mInjectEventStatus
    pub filter_intercept: bool,    // mIsFilterInterceptMode
    pub synergy: bool,             // mSynergyMode
    pub oneway: bool,              // mOnewayMode
    pub pad_mode: bool,            // mPadMode
    pub touch_line: String,        // TouchStates 原文(取证用,原样保留)
    pub touch_pointers: Option<u32>, // 账本里当前按下的触点数;None=没解析出来
    pub raw_pointers: Option<u32>,   // Last Raw Touch: pointerCount=N
    pub cooked_pointers: Option<u32>,// Last Cooked Touch: pointerCount=N
}

