pub fn parse_device_input_state(dump: &str) -> DeviceInputState;

/// 跑一次 `dumpsys input`(走既有 adbcmd,超时 3~5s),失败返回 None
pub fn device_input_state(serial: &str) -> Option<DeviceInputState>;

/// 用 `getevent -pl` 找触摸屏 event 节点(选带 ABS_MT_TRACKING_ID 的;名字含 touch/ts/focaltech/goodix/synaptics 优先)
pub fn touch_screen_path(serial: &str) -> Option<String>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PhysicalTouch { Down, Up }

/// 只读监听"手摸手机屏":起一个线程跑 `adb -s <serial> shell getevent -lt <path>`,
/// 解析 ABS_MT_TRACKING_ID(值 != ffffffff 表示这根手指按下,-1/ffffffff 表示抬起),
/// 用活跃 tracking id 集合算出 0→>0 的 Down 边沿和 >0→0 的 Up 边沿,经 channel 发给界面。
/// 调用方 drop 接收端 ⇒ 发送失败 ⇒ 线程自行退出并 kill 子进程。**绝不注入任何输入。**
pub fn watch_physical_touch(serial: String) -> std::sync::mpsc::Receiver<PhysicalTouch>;
```

