/// 有上限地跑一条只读 adb 查询:超时/失败返回 None(不 panic、不阻塞 GUI)
fn adb_read_within(serial: &str, args: &[&str], timeout: Duration) -> Option<String> {
    let mut child = adb_cmd(Some(serial))
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
