        let mut buf = Vec::new();
        let mut r = std::io::Read::take(stdout, MAX_BYTES);
        let _ = r.read_to_end(&mut buf);
        buf
    });
    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait() {
            Ok(Some(st)) => break Some(st),
            Ok(None) => {
                if Instant::now() >= deadline {
                    let _ = child.kill();
                    break None;
                }
                std::thread::sleep(Duration::from_millis(20));
            }
            Err(_) => break None,
        }
    };
    // 读完 stdout(进程已退出/被杀,读线程会很快收尾)
    let buf = reader.join().ok()?; // join bounded? reader ends when pipe closes after kill
    let status = status?;
    if !status.success() { return None; }
    Some(String::from_utf8_lossy(&buf).to_string())
}
