    /// 喂一行 getevent 输出,返回这一行造成的边沿(可能没有)
    pub(crate) fn feed_line(&mut self, line: &str) -> Option<PhysicalTouch> {
        match parse_getevent_touch_line(line)? {
            TouchEvent::Slot(s) => { self.slot = s; None }
            TouchEvent::TrackingId(t) => {
                if t < 0 { self.slots.remove(&self.slot); } else { self.slots.insert(self.slot, t); }
                let now_down = !self.slots.is_empty();
                if now_down && !self.had_down { self.had_down = true; return Some(PhysicalTouch::Down); }
                if !now_down && self.had_down { self.had_down = false; return Some(PhysicalTouch::Up); }
                None
            }
        }
    }
}
