fn watch_physical_touch_on(serial: &str, path: &str, tx: Sender<PhysicalTouch>) {
    let Ok(mut child) = adb_cmd(Some(serial))
        .args(["shell", "getevent", "-lt", path])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn() else { return; };
    let Some(stdout) = child.stdout.take() else { let _ = child.kill(); return; };
    let mut tracker = TouchEdgeTracker::default();
    for line in BufReader::new(stdout).lines().map_while(Result::ok) {
        if let Some(edge) = tracker.feed_line(&line) {
            if tx.send(edge).is_err() {
                // 接收端已 drop:立即结束并确保子进程不留
                break;
