/// 把 MIUI 那些开关值解析成 bool:`1`/`true`/`on` 为真,`0`/`false`/`off` 为假,
/// 其余(缺字段、格式不认识)返回 None —— 由调用方按"未知"处理。
fn parse_bool_after(text: &str, key: &str) -> Option<bool> {
    let line = text.lines().find(|l| l.contains(key))?;
    let rest = line.split_once(key)?.1.trim_start();
    let rest = rest.trim_start_matches(['=', ':', ' ']);
    let tok: String = rest.chars().take_while(|c| c.is_ascii_alphanumeric() || *c == '_').collect();
    match tok.to_ascii_lowercase().as_str() {
        "1" | "true" | "on" | "yes" => Some(true),
        "0" | "false" | "off" | "no" => Some(false),
        _ => None,
    }
}
