/// 从 TouchStates 的后半段里数触点:AOSP/MIUI 各版本样式不一,只认三种常见写法
/// (`pointerCount=N` / `pointers=N` / `pointer=N`,大小写不敏感),多处出现则求和
/// (多显示器分别打印时就是各显示器的触点相加)。一个都认不出 ⇒ None(未知)。
fn count_pointers_in_states(rest: &str) -> Option<u32> {
    let lower = rest.to_ascii_lowercase();
    let mut total: u32 = 0;
    let mut found = false;
    for key in ["pointercount", "pointers", "pointer"] {
        let mut hay = lower.as_str();
        while let Some(pos) = hay.find(key) {
            let after = &hay[pos + key.len()..];
            let after = after.trim_start_matches(['=', ':', ' ', '\t', '-']);
            let digits: String = after.chars().take_while(|c| c.is_ascii_digit()).collect();
            if !digits.is_empty() {
                if let Ok(n) = digits.parse::<u32>() {
                    total = total.saturating_add(n);
                    found = true;
                }
            }
            hay = &hay[pos + key.len()..];
        }
    }
    found.then_some(total)
}
```

