pub fn watch_physical_touch(serial: String) -> Receiver<PhysicalTouch> {
    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        // 节点查找失败(拔线/adb 抖动/没有触摸屏)⇒ 直接收工,不 panic、不空转
        let Some(path) = touch_screen_path(&serial) else {
            return;
        };
        run_getevent_watch(&serial, &path, tx);
    });
    rx
}

fn run_getevent_watch(serial: &str, path: &str, tx: mpsc::Sender<PhysicalTouch>) {
    let Ok(mut child) = adb_cmd(Some(serial))
        .args(["shell", "getevent", "-lt", path])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
    else {
        return;
    };
    if let Some(stdout) = child.stdout.take() {
        let mut tracker = TouchEdgeTracker::default();
        for line in BufReader::new(stdout).lines().map_while(Result::ok) {
            let Some(edge) = tracker.feed_line(&line) else { continue };
            // 接收端 drop ⇒ 发送失败 ⇒ 立刻收工(这是本函数唯一的退出条件之一)
            if tx.send(edge).is_err() {
                break;
            }
        }
    }
    // 收尾必须有界:kill + try_wait 轮询,绝不无条件 wait(与 ControlServer::drop 同口径)
    kill_child_bounded(&mut child, Duration::from_millis(800));
}
```

