```rust
/// 有上限地跑一条**只读** adb 查询,返回 stdout(超时/失败/被杀 ⇒ None)。
///
/// `Command::output()` 没有任何超时:在 adb server 卡住时会把调用线程永久挂住。
/// 这条探针跑在自愈/巡检路径上,绝不能被一条查询卡死,所以:
/// spawn → 读线程抽干 stdout(防止管道写满互锁)→ 主线程按 deadline 轮询 try_wait
/// → 超时就 kill。两个等待(进程退出、stdout 读干)各自都有上限。
fn adb_read_within(serial: &str, args: &[&str], timeout: Duration) -> Option<String> {
    let mut child = adb_cmd(Some(serial))
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .ok()?;
    let stdout = child.stdout.take()?;
    let (tx, rx) = mpsc::channel::<Vec<u8>>();
    std::thread::spawn(move || {
        let mut buf = Vec::new();
        // 上限:只读查询的输出不可能需要更多;防止对端一直吐导致内存无界
        let _ = Read::take(stdout, MAX_READ_BYTES).read_to_end(&mut buf);
        let _ = tx.send(buf);
    });
    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait() {
            Ok(Some(st)) => break Some(st),
            Ok(None) if Instant::now() >= deadline => {
                let _ = child.kill();
                break None;
            }
            Ok(None) => std::thread::sleep(Duration::from_millis(20)),
            Err(_) => break None,
        }
    };
    let status = status?;
    let buf = rx.recv_timeout(Duration::from_millis(500)).ok()?;
    if !status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&buf).to_string())
}
```

