        if trimmed.contains("ABS (") {
            in_abs = true;
        } else if ["KEY (", "REL (", "SW (", "MSC (", "LED (", "FF (", "input props"]
            .iter()
            .any(|k| trimmed.contains(k))
        {
            in_abs = false;
        }
        if in_abs && abs_line_has_tracking_id(trimmed) {
            cur.has_tracking_id = true;
        }
    }
    out
}
