        assert_eq!(parse_getevent_touch_line("EV_ABS"), None);
        assert_eq!(parse_getevent_touch_line("[ 1.0] /dev/input/event5:"), None);
        assert_eq!(
            parse_getevent_touch_line(
                "[ 1.0] /dev/input/event5: EV_ABS ABS_MT_TRACKING_ID zzzz"
